import React,{useState} from 'react';
import {useWorkbenchPreferences} from '../../shared/preferences.tsx';
import {editorDefaults,proseAppearance} from '../../shared/editor-preferences.mjs';
function Range({label,name,min,max,step=1,unit=''}){const {preferences:p,update}=useWorkbenchPreferences();return <label className="chapter-setting"><span>{label}</span><input aria-label={label} type="range" min={min} max={max} step={step} value={p[name]} onChange={e=>update({[name]:Number(e.target.value)})}/><output>{p[name]}{unit}</output></label>;}
function Toggle({label,name,note}){const {preferences:p,update}=useWorkbenchPreferences();return <label className="chapter-setting switch"><span>{label}{note&&<small>{note}</small>}</span><input type="checkbox" checked={p[name]} onChange={e=>update({[name]:e.target.checked})}/></label>;}
export function ChapterTypography(){const {preferences:p,update,error}=useWorkbenchPreferences();return <div className="chapter-settings"><p className="chapter-tool-note">仅改变此设备显示，不修改小说原文。</p><Range label="正文字号" name="fontSize" min={14} max={32} unit="px"/><label className="chapter-setting"><span>字体</span><select aria-label="正文字体" value={p.fontFamily} onChange={e=>update({fontFamily:e.target.value})}><option value="system">系统默认</option><option value="serif">宋体 / 衬线</option><option value="sans">黑体 / 无衬线</option><option value="mono">等宽字体</option></select></label><label className="chapter-setting"><span>文字颜色<small>自动颜色适配明暗主题</small></span><input aria-label="正文自定义颜色" type="color" value={p.fontColor==='auto'?'#333333':p.fontColor} onChange={e=>update({fontColor:e.target.value})}/><button onClick={()=>update({fontColor:'auto'})} aria-pressed={p.fontColor==='auto'}>自动</button></label><label className="chapter-setting"><span>字重</span><select aria-label="正文字重" value={p.fontWeight} onChange={e=>update({fontWeight:Number(e.target.value)})}>{[[300,'略细'],[400,'常规'],[500,'略粗'],[600,'半粗'],[700,'粗体']].map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></label><Toggle label="斜体显示" name="fontItalic"/><Toggle label="下划线显示" name="fontUnderline"/><div className="chapter-font-preview"><small>正文预览</small><p style={proseAppearance(p)}>雨停以后，街道重新安静下来。窗边的灯仍亮着，故事还在继续。</p></div><button onClick={()=>update(Object.fromEntries(['fontSize','fontFamily','fontColor','fontWeight','fontItalic','fontUnderline'].map(key=>[key,editorDefaults[key]])))}>恢复默认字体</button><p className="chapter-tool-note" role="status">{error||'偏好自动保存在此浏览器'}</p></div>;}
export function ChapterLayout(){const {preferences:p,update}=useWorkbenchPreferences();return <div className="chapter-settings"><label className="chapter-setting"><span>章节标题</span><select value={p.titleAlign} onChange={e=>update({titleAlign:e.target.value})}>{[['left','居左'],['center','居中'],['right','居右'],['hidden','隐藏']].map(([v,label])=><option key={v} value={v}>{label}</option>)}</select></label><Range label="字间距" name="letterSpacing" min={0} max={8} step={.5} unit="px"/><Range label="行间距" name="leading" min={1.3} max={3} step={.05}/><Range label="桌面左右边距" name="pageMargin" min={8} max={80} unit="px"/><Range label="窄屏左右边距" name="mobilePageMargin" min={4} max={32} unit="px"/><Range label="额外底部安全距离" name="bottomSpace" min={16} max={160} step={8} unit="px"/><Toggle label="底部信息栏" name="showInfoBar" note="关闭后仍显示保存失败和冲突提示"/><Toggle label="标题栏透明" name="transparentTitle"/><p className="chapter-tool-note">宿主顶部、聊天框和系统安全区避让会继续保留，不受自定义距离覆盖。</p><button onClick={()=>update(Object.fromEntries(['titleAlign','letterSpacing','leading','pageMargin','mobilePageMargin','bottomSpace','showInfoBar','transparentTitle'].map(key=>[key,editorDefaults[key]])))}>恢复默认布局</button></div>;}
export function ChapterFormat({apply,undo,disabled}){const [options,setOptions]=useState({indent:2,blankLines:1,trimSpaces:true});return <div className="chapter-settings"><p className="chapter-tool-note">下面会实际修改本章正文。只有点击“应用排版”才执行；操作后可撤销，继续写作后不会用旧全文覆盖新稿。</p><label className="chapter-setting"><span>段首缩进</span><select value={options.indent} onChange={e=>setOptions(o=>({...o,indent:e.target.value}))}><option value="preserve">保留原缩进</option><option value="0">无缩进</option><option value="2">缩进 2 字符</option><option value="4">缩进 4 字符</option></select></label><label className="chapter-setting"><span>段间空行</span><select value={options.blankLines} onChange={e=>setOptions(o=>({...o,blankLines:Number(e.target.value)}))}><option value={0}>不空行</option><option value={1}>空一行</option><option value={2}>空两行</option></select></label><label className="chapter-setting switch"><span>清理行首尾和重复空格</span><input type="checkbox" checked={options.trimSpaces} onChange={e=>setOptions(o=>({...o,trimSpaces:e.target.checked}))}/></label><div className="row"><button onClick={()=>setOptions({indent:2,blankLines:1,trimSpaces:true})}>恢复选项默认</button><button disabled={disabled} className="primary" onClick={()=>apply(options)}>应用排版</button>{undo&&<button onClick={undo}>撤销上次文本操作</button>}</div></div>;}
export function ChapterEditingPreferences(){const {preferences:p,update}=useWorkbenchPreferences();return <div className="chapter-settings"><Toggle label="打开章节定位末尾" name="openAtEnd"/><label className="chapter-setting"><span>字数显示位置<small>默认在底部；顶部显示不受底部信息栏开关影响</small></span><select aria-label="字数显示位置" value={p.wordCountPosition} onChange={e=>update({wordCountPosition:e.target.value})}><option value="bottom">底部</option><option value="top">顶部</option></select></label><Toggle label="字数包含标点" name="countPunctuation" note="始终不计空白；关闭时不计标点和符号"/><p className="chapter-tool-note">手机方向仅在宿主支持时可锁定；不支持时请使用系统方向设置。</p><OrientationControl/></div>;}
export function OrientationControl(){const [message,setMessage]=useState('');if(!window.matchMedia('(pointer: coarse)').matches&&document.documentElement.dataset.hostPlatform!=='mobile')return null;const lock=async value=>{try{if(value==='system'){if(typeof screen.orientation?.unlock!=='function'){setMessage('当前宿主不提供方向控制，将跟随系统设置。');return;}screen.orientation.unlock();setMessage('已取消本页方向锁定，跟随系统。');return;}if(typeof screen.orientation?.lock!=='function')throw new Error('当前宿主不支持方向锁定，请使用手机系统方向设置。');await screen.orientation.lock(value);setMessage(`宿主已接受${value==='portrait'?'竖屏':'横屏'}锁定。`);}catch(e){setMessage(e?.message?.includes('当前宿主')?e.message:'当前宿主未允许锁定方向，请使用手机系统方向设置。');}};return <div><div className="row" aria-label="手机方向"><button onClick={()=>lock('system')}>跟随系统</button><button onClick={()=>lock('portrait')}>竖屏</button><button onClick={()=>lock('landscape')}>横屏</button></div>{message&&<p role="status">{message}</p>}</div>;}
